'      <strong>Registered angles:</strong>',
unistr('      CENTER \00B7 LEFT \00B7 RIGHT \00B7 UP \00B7 DOWN'),
'    </div>',
'  </section>',
'',
'',
'  <section class="fa-sec">',
'    <div class="fa-head">',
