'',
'      <div class="fa-card fa-tech">',
'        <span class="fa-tag">Markup</span>',
'        <h3>HTML5</h3>',
'        <p>Browser interface and camera support.</p>',
'      </div>',
'',
'      <div class="fa-card fa-tech">',
'        <span class="fa-tag">Styling</span>',
'        <h3>CSS3</h3>',
'        <p>Responsive project interface.</p>',
