'',
'.face-countdown {',
'    position: absolute;',
'    inset: 0;',
'',
'    z-index: 10;',
'',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'',
'    background:',
'        rgba(0, 0, 0, 0.18);',
'}',
'',
'.face-countdown.hidden {',
'    display: none;',
'}',
'',
'#faceCountdownNumber {',
'    width: 86px;',
'    height: 86px;',
'',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'',
'    border-radius: 50%;',
'',
'    background:',
'        rgba(17, 24, 39, 0.88);',
'',
'    border:',
'        3px solid',
'        rgba(96, 165, 250, 0.9);',
'',
'    color: #fff;',
'',
'    font-size: 46px;',
'    font-weight: 800;',
'',
'    box-shadow:',
'        0 0 30px',
'        rgba(37, 99, 235, 0.30);',
'',
'    animation:',
'        countdownPulse 1s ease;',
'}',
'',
'@keyframes countdownPulse {',
'    0% {',
'        transform: scale(0.65);',
'        opacity: 0;',
'    }',
'',
'    55% {',
'        transform: scale(1.05);',
'        opacity: 1;',
'    }',
'',
'    100% {',
'        transform: scale(1);',
'    }',
'}',
'',
'/* =========================================================',
'   FLASH',
'   ========================================================= */',
'',
'.face-capture-flash {',
'    position: absolute;',
'    inset: 0;',
'',
'    z-index: 20;',
'',
'    background: #fff;',
'',
'    opacity: 0;',
'',
'    pointer-events: none;',
'}',
'',
'.face-capture-flash.active {',
'    animation:',
'        captureFlash 0.3s ease;',
'}',
'',
'@keyframes captureFlash {',
'    0% {',
'        opacity: 0;',
'    }',
'',
'    40% {',
'        opacity: 0.85;',
'    }',
'',
'    100% {',
'        opacity: 0;',
'    }',
'}',
'',
'/* =========================================================',
'   STATUS',
'   ========================================================= */',
'',
'.face-status {',
'    min-height: 38px;',
'',
'    display: flex;',
'    align-items: center;',
'',
'    padding: 0 13px;',
'',
'    background: #f9fafb;',
'',
'    color: #4b5563;',
'',
'    font-size: 11px;',
'    font-weight: 650;',
'}',
'',
'/* =========================================================',
'   INSTRUCTIONS CARD',
'   ========================================================= */',
'',
'.face-instructions-card {',
'    min-height: 100%;',
'',
'    padding: 20px;',
'',
'    display: flex;',
'    flex-direction: column;',
'',
'    justify-content: center;',
'}',
'',
'.face-instruction-icon {',
'    width: 46px;',
'    height: 46px;',
'',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'',
'    margin-bottom: 14px;',
'',
'    border-radius: 13px;',
'',
'    background:',
'        rgba(37, 99, 235, 0.09);',
'',
'    color: #2563eb;',
'',
'    font-size: 20px;',
'}',
'',
'.face-instruction-label {',
'    display: block;',
'',
'    margin-bottom: 4px;',
'',
'    color: #9ca3af;',
'',
'    font-size: 9px;',
'    font-weight: 800;',
'',
'    text-transform: uppercase;',
'',
'    letter-spacing: 0.08em;',
'}',
'',
'.face-instructions-card h3 {',
'    margin: 0 0 8px;',
'',
'    font-size: 22px;',
'    line-height: 1.2;',
'',
'    font-weight: 750;',
'}',
'',
'.face-instructions-card p {',
'    margin: 0;',
'',
'    max-width: 300px;',
'',
'    color: #6b7280;',
'',
'    font-size: 12px;',
'    line-height: 1.6;',
'}',
'',
'/* Hold indicator */',
'',
'.face-hold-indicator {',
'    margin-top: 18px;',
'',
'    display: flex;',
'    align-items: center;',
