'',
'    background: #f8fafc;',
'',
'    color: #6b7280;',
'',
'    font-size: 11px;',
'    font-weight: 700;',
'}',
'',
'.hold-dot {',
'    width: 8px;',
'    height: 8px;',
'',
'    flex: 0 0 8px;',
'',
'    border-radius: 50%;',
'',
'    background: #9ca3af;',
'}',
'',
'.hold-dot.ready {',
'    background: #22c55e;',
'',
'    box-shadow:',
'        0 0 0 4px',
'        rgba(34, 197, 94, 0.10);',
'}',
'',
'/* =========================================================',
'   FOOTER',
'   ========================================================= */',
'',
'.face-registration-footer {',
'    margin-top: 14px;',
'',
'    display: flex;',
'    align-items: center;',
'    justify-content: space-between;',
'',
'    gap: 16px;',
'',
'    padding: 12px 14px;',
'',
'    border:',
'        1px solid #e5e7eb;',
'',
'    border-radius: 13px;',
'',
'    background: #fff;',
'',
'    box-shadow:',
'        0 4px 16px rgba(15, 23, 42, 0.035);',
'}',
'',
'.face-security-info {',
'    min-width: 0;',
'',
'    display: flex;',
'    align-items: center;',
'    gap: 7px;',
'',
'    color: #6b7280;',
'',
'    font-size: 10px;',
'    line-height: 1.4;',
'}',
'',
'.face-security-info .fa {',
'    flex: 0 0 auto;',
'    color: #16a34a;',
'}',
'',
'.face-actions {',
'    flex: 0 0 auto;',
'',
'    display: flex;',
'    align-items: center;',
'    gap: 8px;',
'}',
'',
'.face-actions button {',
'    min-width: 132px;',
'    height: 34px;',
'',
'    font-size: 11px;',
'    font-weight: 700;',
'}',
'',
'/* =========================================================',
'   TABLET',
