);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(100671585278207187248)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SAVE_FACE_SAMPLES'
,p_static_id=>'save-face-samples'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_user_id          FA_USERS.ID%TYPE;',
'    l_face_profile_id  FA_FACE_PROFILES.FACE_PROFILE_ID%TYPE;',
'',
'    l_center CLOB := APEX_APPLICATION.G_X01;',
'    l_left   CLOB := APEX_APPLICATION.G_X02;',
'    l_right  CLOB := APEX_APPLICATION.G_X03;',
'    l_up     CLOB := APEX_APPLICATION.G_X04;',
'    l_down   CLOB := APEX_APPLICATION.G_X05;',
'',
'    l_g_user VARCHAR2(255);',
'',
'',
'    FUNCTION is_valid_descriptor(',
'        p_descriptor CLOB',
'    ) RETURN BOOLEAN',
'    IS',
'        l_count NUMBER;',
'    BEGIN',
'',
'        IF p_descriptor IS NULL THEN',
'            RETURN FALSE;',
'        END IF;',
'',
'        SELECT COUNT(*)',
'        INTO l_count',
'        FROM JSON_TABLE(',
'            p_descriptor,',
'            ''$[*]''',
'            COLUMNS (',
'                val NUMBER PATH ''$''',
'            )',
'        );',
'',
'        RETURN l_count = 128;',
'',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            RETURN FALSE;',
'    END;',
'',
'',
'    PROCEDURE insert_sample(',
'        p_profile_id NUMBER,',
'        p_angle      VARCHAR2,',
'        p_descriptor CLOB',
'    )',
'    IS',
'    BEGIN',
'',
'        INSERT INTO FA_FACE_SAMPLES',
'        (',
'            FACE_PROFILE_ID,',
'            ANGLE_CODE,',
'            FACE_DESCRIPTOR,',
'            CAPTURED_AT',
'        )',
'        VALUES',
'        (',
'            p_profile_id,',
'            p_angle,',
'            p_descriptor,',
'            SYSTIMESTAMP',
'        );',
'',
'    END;',
'',
'BEGIN',
'',
'    /* 1. Current APEX user */',
'',
'    l_g_user := TRIM(APEX_APPLICATION.G_USER);',
'',
'    IF l_g_user IS NULL',
'       OR UPPER(l_g_user) = ''NOBODY''',
'    THEN',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20500,',
'            ''Authenticated APEX user was not found.''',
'        );',
'',
'    END IF;',
'',
'',
'    /* 2. Validate descriptors */',
'',
'    IF NOT is_valid_descriptor(l_center) THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20501,',
'            ''Invalid CENTER descriptor.''',
'        );',
'    END IF;',
'',
'    IF NOT is_valid_descriptor(l_left) THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20502,',
'            ''Invalid LEFT descriptor.''',
'        );',
'    END IF;',
'',
'    IF NOT is_valid_descriptor(l_right) THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20503,',
'            ''Invalid RIGHT descriptor.''',
'        );',
'    END IF;',
'',
'    IF NOT is_valid_descriptor(l_up) THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20504,',
'            ''Invalid UP descriptor.''',
'        );',
'    END IF;',
'',
'    IF NOT is_valid_descriptor(l_down) THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20505,',
'            ''Invalid DOWN descriptor.''',
'        );',
'    END IF;',
'',
'',
'    /* 3. Find active user */',
'',
'    BEGIN',
'',
'        SELECT ID',
'        INTO l_user_id',
'        FROM FA_USERS',
'        WHERE ACCOUNT_STATUS = 1',
'          AND (',
'                UPPER(USERNAME) = UPPER(l_g_user)',
'                OR',
'                LOWER(EMAIL) = LOWER(l_g_user)',
'              )',
'        FETCH FIRST 1 ROW ONLY;',
'',
'    EXCEPTION',
'',
'        WHEN NO_DATA_FOUND THEN',
'',
'            RAISE_APPLICATION_ERROR(',
'                -20510,',
'                ''Active user was not found. G_USER = ['' ||',
'                l_g_user ||',
'                '']''',
'            );',
'',
'    END;',
'',
'',
'    /* 4. Find or create face profile */',
'',
'    BEGIN',
'',
'        SELECT FACE_PROFILE_ID',
'        INTO l_face_profile_id',
'        FROM FA_FACE_PROFILES',
'        WHERE USER_ID = l_user_id;',
'',
'    EXCEPTION',
'',
'        WHEN NO_DATA_FOUND THEN',
'',
'            INSERT INTO FA_FACE_PROFILES',
'            (',
'                USER_ID,',
'                CREATED_AT',
'            )',
'            VALUES',
'            (',
'                l_user_id,',
'                SYSTIMESTAMP',
'            )',
'            RETURNING FACE_PROFILE_ID',
'            INTO l_face_profile_id;',
'',
'    END;',
'',
'',
'    /* 5. Delete previous samples */',
'',
'    DELETE FROM FA_FACE_SAMPLES',
'    WHERE FACE_PROFILE_ID = l_face_profile_id;',
'',
'',
'    /* 6. Insert five samples */',
'',
'    insert_sample(',
'        l_face_profile_id,',
'        ''CENTER'',',
'        l_center',
'    );',
'',
'    insert_sample(',
'        l_face_profile_id,',
'        ''LEFT'',',
'        l_left',
'    );',
'',
'    insert_sample(',
'        l_face_profile_id,',
'        ''RIGHT'',',
'        l_right',
'    );',
'',
'    insert_sample(',
'        l_face_profile_id,',
'        ''UP'',',
'        l_up',
'    );',
'',
'    insert_sample(',
'        l_face_profile_id,',
'        ''DOWN'',',
'        l_down',
'    );',
'',
'',
'    /* 7. Update profile timestamp */',
'',
'    UPDATE FA_FACE_PROFILES',
'    SET UPDATED_AT = SYSTIMESTAMP',
'    WHERE FACE_PROFILE_ID = l_face_profile_id;',
'',
'',
'    /* 8. Commit */',
'',
'    COMMIT;',
'',
'',
'    /* 9. JSON response */',
'',
'    APEX_JSON.OPEN_OBJECT;',
'',
'    APEX_JSON.WRITE(',
'        ''success'',',
'        TRUE',
'    );',
'',
'    APEX_JSON.WRITE(',
'        ''message'',',
'        ''All five face samples were saved successfully.''',
'    );',
'',
'    APEX_JSON.WRITE(',
'        ''samples'',',
'        5',
'    );',
'',
'    APEX_JSON.WRITE(',
'        ''user_id'',',
'        l_user_id',
'    );',
'',
'    APEX_JSON.WRITE(',
'        ''face_profile_id'',',
'        l_face_profile_id',
'    );',
'',
'    APEX_JSON.CLOSE_OBJECT;',
'',
'',
'EXCEPTION',
'',
'    WHEN OTHERS THEN',
'',
'        ROLLBACK;',
'',
'        APEX_JSON.OPEN_OBJECT;',
'',
'        APEX_JSON.WRITE(',
'            ''success'',',
'            FALSE',
'        );',
'',
'        APEX_JSON.WRITE(',
'            ''message'',',
'            SQLERRM',
'        );',
'',
'        APEX_JSON.WRITE(',
'            ''error_code'',',
'            SQLCODE',
'        );',
'',
'        APEX_JSON.CLOSE_OBJECT;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>100671585278207187248
,p_created_on=>wwv_flow_imp.dz('20260913190054Z')
,p_updated_on=>wwv_flow_imp.dz('20260914033350Z')
,p_created_by=>'MIDOHEMA94@GMAIL.COM'
,p_updated_by=>'MIDOHEMA94@GMAIL.COM'
);
end;
/
prompt --application/pages/page_09999
begin
wwv_flow_imp_page.create_page(
 p_id=>9999
,p_name=>'Login Page'
,p_alias=>'LOGIN'
,p_step_title=>'Face Authentication - Log In'
,p_warn_on_unsaved_changes=>'N'
,p_first_item=>'AUTO_FIRST_ITEM'
,p_autocomplete_on_off=>'OFF'
,p_javascript_file_urls=>'#APP_FILES#face-api.min.js'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const MODEL_URL = ''#APP_FILES#models/'';',
'',
'let faceLoginStream = null;',
'let faceLoginRunning = false;',
'let faceLoginVerifying = false;',
'',
'console.log("Face API:", typeof faceapi);',
'',
'Promise.all([',
'    faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL),',
'    faceapi.nets.faceLandmark68TinyNet.loadFromUri(MODEL_URL),',
'    faceapi.nets.faceRecognitionNet.loadFromUri(MODEL_URL)',
'])',
'    .then(function () {',
'',
unistr('        console.log("\2705 Tiny Face Detector loaded");'),
unistr('        console.log("\2705 Tiny Face Landmark 68 loaded");'),
unistr('        console.log("\2705 Face Recognition loaded");'),
'',
'    })',
'    .catch(function (error) {',
'',
unistr('        console.error("\274C Face model loading failed:", error);'),
'',
'    });',
'',
'',
'window.startFaceLoginCamera = async function () {',
'',
'    const video =',
'        document.getElementById("faceLoginVideo");',
'',
'    const status =',
'        document.getElementById("faceLoginStatus");',
'',
'    if (!video) {',
unistr('        console.error("\274C faceLoginVideo not found");'),
'        return;',
'    }',
'',
'    try {',
'',
'        if (faceLoginStream) {',
'            faceLoginStream',
'                .getTracks()',
'                .forEach(function (track) {',
'                    track.stop();',
'                });',
'        }',
'',
'        faceLoginStream =',
'            await navigator.mediaDevices.getUserMedia({',
'                video: {',
'                    facingMode: "user",',
'                    width: {',
'                        ideal: 640',
'                    },',
'                    height: {',
'                        ideal: 480',
'                    }',
'                },',
'                audio: false',
'            });',
'',
'        video.srcObject = faceLoginStream;',
'',
'        await video.play();',
'',
'        faceLoginRunning = true;',
'',
'        if (status) {',
'            status.textContent =',
'                "Camera ready. Look at the camera.";',
'        }',
'',
unistr('        console.log("\2705 Face login camera started");'),
'',
'        detectFaceLogin();',
'',
'    } catch (error) {',
'',
'        console.error(',
unistr('            "\274C Camera error:",'),
'            error',
'        );',
'',
'        if (status) {',
'            status.textContent =',
'                "Unable to access the camera.";',
'        }',
'',
'    }',
'',
'};',
'',
'',
'async function detectFaceLogin() {',
'',
'    const video =',
'        document.getElementById("faceLoginVideo");',
'',
'    const status =',
'        document.getElementById("faceLoginStatus");',
'',
'    if (!video || !faceLoginRunning) {',
'        return;',
'    }',
'',
'    if (video.readyState >= 2) {',
'',
'        try {',
'',
'            const detection =',
'                await faceapi',
'                    .detectSingleFace(',
'                        video,',
'                        new faceapi.TinyFaceDetectorOptions({',
'                            inputSize: 416,',
'                            scoreThreshold: 0.35',
'                        })',
'                    )',
'                    .withFaceLandmarks(true)',
'                    .withFaceDescriptor();',
'',
'            if (detection) {',
'',
'                status.textContent =',
'                    "Face detected. Verifying...";',
'',
'                /*',
'                 * Prevent multiple Ajax requests',
'                 */',
'                if (!faceLoginVerifying) {',
'',
'                    faceLoginVerifying = true;',
'',
'                    const descriptor =',
'                        Array.from(detection.descriptor);',
'',
'                    const identifier =',
'                        apex.item("P9999_USERNAME")',
'                            .getValue()',
'                            .trim();',
'',
'                    console.log(',
unistr('                        "\2705 Face descriptor generated",'),
'                        "Length:",',
'                        descriptor.length',
'                    );',
'',
'                    verifyFaceLogin(',
'                        identifier,',
'                        descriptor',
'                    );',
'                }',
'',
'            } else {',
'',
'                status.textContent =',
'                    "Looking for your face...";',
'',
'            }',
'',
'        } catch (error) {',
'',
'            console.error(',
unistr('                "\274C Face detection error:",'),
'                error',
'            );',
'',
'        }',
'',
'    }',
'',
'    requestAnimationFrame(',
'        detectFaceLogin',
'    );',
'}',
'async function verifyFaceLogin(identifier, descriptor) {',
'',
'    const status =',
'        document.getElementById("faceLoginStatus");',
'',
'    try {',
'',
unistr('        console.log("\D83D\DD10 Sending face verification...");'),
'',
'        apex.server.process(',
'            "VERIFY_FACE_LOGIN",',
'            {',
'                x01: identifier,',
'                x02: JSON.stringify(descriptor)',
'            },',
'            {',
'                /*',
'                 * POST_LOGIN may return an APEX HTML page',
'                 * after successful authentication.',
'                 */',
'                dataType: "text",',
'',
'                success: function (response) {',
'',
'                    console.log(',
unistr('                        "\D83D\DD10 Face verification response received."'),
'                    );',
'',
'                    /*',
'                     * Successful POST_LOGIN may return HTML.',
'                     * Redirect immediately.',
'                     */',
'                    if (',
'                        typeof response === "string" &&',
'                        response.toLowerCase().indexOf("<!doctype html") !== -1',
'                    ) {',
'',
'                        console.log(',
unistr('                            "\2705 APEX authentication successful."'),
'                        );',
'',
'                        status.textContent =',
unistr('                            "\2705 Face verified. Logging you in...";'),
'',
'                        stopFaceLoginCamera();',
'',
'                        setTimeout(function () {',
'',
'                            apex.navigation.redirect(',
'                                "f?p=" +',
'                                $v("pFlowId") +',
'                                ":1:" +',
'                                $v("pInstance")',
'                            );',
'',
'                        }, 300);',
'',
'                        return;',
'                    }',
'',
'',
'                    /*',
'                     * Parse JSON response',
'                     */',
'                    let data;',
'',
'                    try {',
'',
'                        data = JSON.parse(response);',
'',
'                    } catch (parseError) {',
'',
'                        console.error(',
unistr('                            "\274C Invalid server response:",'),
'                            response',
'                        );',
'',
'                        apex.message.alert(',
'                            "An unexpected error occurred during face verification."',
'                        );',
'',
'                        faceLoginVerifying = false;',
'',
'                        return;',
'                    }',
'',
'',
'                    console.log(',
unistr('                        "\D83D\DD10 Verification result:",'),
'                        data',
'                    );',
'',
'',
'                    /*',
'                     * User does not exist',
'                     */',
'                    if (data.status === "USER_NOT_FOUND") {',
'',
'                        stopFaceLoginCamera();',
'',
'                        apex.message.alert(',
'                            "User not found.\n\n" +',
'                            "Please enter a valid Username or Email.",',
'                            function () {',
'',
'                                faceLoginVerifying = false;',
'',
'                                const usernameItem =',
'                                    apex.item("P9999_USERNAME");',
'',
'                                usernameItem.setFocus();',
'',
'                            }',
'                        );',
'',
'                        return;',
'                    }',
'',
'',
'                    /*',
'                     * No face profile',
'                     */',
'                    if (data.status === "NO_FACE_PROFILE") {',
'',
'                        stopFaceLoginCamera();',
'',
'                        apex.message.alert(',
'                            "Face ID is not registered for this user.",',
'                            function () {',
'',
'                                faceLoginVerifying = false;',
'',
'                            }',
'                        );',
'',
'                        return;',
'                    }',
'',
'',
'                    /*',
'                     * No face samples',
'                     */',
'                    if (data.status === "NO_FACE_SAMPLES") {',
'',
'                        stopFaceLoginCamera();',
'',
'                        apex.message.alert(',
'                            "No Face ID samples are registered for this user.",',
'                            function () {',
'',
'                                faceLoginVerifying = false;',
'',
'                            }',
'                        );',
'',
'                        return;',
'                    }',
'',
'',
'                    /*',
'                     * Face does not match',
'                     */',
'                    if (',
'                        data.status === "NO_MATCH"',
'                    ) {',
'',
'                        stopFaceLoginCamera();',
'',
'                        apex.message.alert(',
'                            "Face not recognized.\n\n" +',
'                            "The face does not match the registered Face ID.",',
'                            function () {',
'',
'                                faceLoginVerifying = false;',
'',
'                            }',
'                        );',
'',
'                        return;',
'                    }',
'',
'',
'                    /*',
'                     * Invalid descriptor',
'                     */',
'                    if (',
'                        data.status === "INVALID_DESCRIPTOR"',
'                    ) {',
'',
'                        stopFaceLoginCamera();',
'',
'                        apex.message.alert(',
'                            "Unable to verify your face.\n\n" +',
'                            "Please try again.",',
'                            function () {',
'',
'                                faceLoginVerifying = false;',
'',
'                            }',
'                        );',
'',
'                        return;',
'                    }',
'',
'',
'                    /*',
'                     * Descriptor missing',
'                     */',
'                    if (',
'                        data.status === "DESCRIPTOR_REQUIRED"',
'                    ) {',
'',
'                        stopFaceLoginCamera();',
'',
'                        apex.message.alert(',
'                            "Face verification could not start.",',
'                            function () {',
'',
'                                faceLoginVerifying = false;',
'',
'                            }',
'                        );',
'',
'                        return;',
'                    }',
'',
'',
'                    /*',
'                     * Username missing',
'                     */',
'                    if (',
'                        data.status === "USERNAME_REQUIRED"',
'                    ) {',
'',
'                        stopFaceLoginCamera();',
'',
'                        apex.message.alert(',
'                            "Please enter your Username or Email first.",',
'                            function () {',
'',
'                                faceLoginVerifying = false;',
'',
'                            }',
'                        );',
'',
'                        return;',
'                    }',
'',
'',
'                    /*',
'                     * General server error',
'                     */',
'                    if (',
'                        data.status === "ERROR"',
'                    ) {',
'',
'                        stopFaceLoginCamera();',
'',
'                        apex.message.alert(',
'                            data.message ||',
'                            "An error occurred during face verification.",',
'                            function () {',
'',
'                                faceLoginVerifying = false;',
'',
'                            }',
'                        );',
'',
'                        return;',
'                    }',
'',
'',
'                    /*',
'                     * Unexpected response',
'                     */',
'                    apex.message.alert(',
'                        data.message ||',
'                        "Face verification failed.",',
'                        function () {',
'',
'                            faceLoginVerifying = false;',
'',
'                        }',
'                    );',
'                },',
'',
'',
'                error: function (',
'                    jqXHR,',
'                    textStatus,',
'                    errorThrown',
'                ) {',
'',
'                    console.error(',
unistr('                        "\274C Face verification Ajax error:",'),
'                        textStatus,',
'                        errorThrown',
'                    );',
'',
'                    console.error(',
'                        "Response:",',
'                        jqXHR.responseText',
'                    );',
'',
'                    status.textContent =',
'                        "Verification failed. Please try again.";',
'',
'                    faceLoginVerifying = false;',
'                }',
'            }',
'        );',
'',
'    } catch (error) {',
'',
'        console.error(',
unistr('            "\274C Verification error:",'),
'            error',
'        );',
'',
'        status.textContent =',
'            "Verification failed.";',
'',
'        faceLoginVerifying = false;',
'    }',
'}',
'',
'window.stopFaceLoginCamera = function () {',
'',
'    faceLoginRunning = false;',
'',
'    if (faceLoginStream) {',
'',
'        faceLoginStream',
'            .getTracks()',
'            .forEach(function (track) {',
'                track.stop();',
'            });',
'',
'        faceLoginStream = null;',
'    }',
'',
'    const video =',
'        document.getElementById("faceLoginVideo");',
'',
'    if (video) {',
'        video.srcObject = null;',
'    }',
'',
'    console.log(',
unistr('        "\D83D\DED1 Face login camera stopped"'),
'    );',
'',
'};',
'',
'/*============================*/',
'setTimeout(function () {',
'',
'    const video = document.getElementById("faceLoginVideo");',
'',
'    if (video) {',
'        video.style.display = "block";',
'        video.style.width = "100%";',
'        video.style.height = "auto";',
'        video.style.minHeight = "300px";',
'        video.style.objectFit = "cover";',
'        video.style.background = "#000";',
'    }',
'',
'}, 1000);'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
